import*as THREE from'three';import{Component,materials}from'../../core/index.js';import{roundedRect}from'../../core/geometry.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,FACE}from'../../modeling/parts.js';import{grove,sma}from'./connectors.js';import{Antenna}from'./Antenna.js';import{spec}from'./dimensions.js';import{addStickers}from'./stickers.js';import data from'./geometry-data.js';const tau=Math.PI*2;
function solid(parent,s,d,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,p,n);}
function ring(parent,outer,inner,d,p,m,n){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return solid(parent,s,d,p,m,n);}
function rearSlab(parent,w,h,d,r,pos,m,n){const o=slab(parent,w,h,d,r,pos,m,[],.015);o.quaternion.copy(FACE.back);o.name=n;return o;}
function board(host){const s=new THREE.Shape(),x=10.2,r=3.8,row=-20,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-5.5,-30);s.lineTo(-8.4,-30);s.lineTo(-x,-28.2);s.lineTo(-x,row-dy);s.absarc(-8,row,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,22);s.lineTo(-8.5,23.7);s.lineTo(8.5,23.7);s.lineTo(x,22);s.lineTo(x,row+dy);s.absarc(8,row,r,a,tau-a,false);s.lineTo(x,-28.2);s.lineTo(8.4,-30);s.lineTo(5.5,-30);s.lineTo(5.5,-25);s.lineTo(-5.5,-25);s.closePath();for(const[x,y,r]of[[0,-20,1.9],...[-3,-1,1,3].map(x=>[x,-24.1,.45])]){const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);}const green=materials.plastic(0x275b3d,{roughness:.9}),metal=materials.metal(0xb6bdaf,{roughness:.48}),dark=materials.plastic(0x1b221d,{roughness:.86}),ceramic=materials.plastic(0xb2a47e,{roughness:.88}),pcb=solid(host.body,s,.8,[0,0,1.6],green,'Cat1-CN own shaped carrier PCB with mounting reliefs and true retaining/Grove solder bores');pcb.userData={role:'physical-pcb',installationInferred:true};const pads=[],barrels=[];for(const x of[-3,-1,1,3]){pads.push(ring(host.body,.7,.28,.06,[x,-24.1,2.4],metal,'Cat1-CN real Grove annular solder land'));barrels.push(ring(host.body,.45,.28,.8,[x,-24.1,1.6],metal,'Cat1-CN real Grove plated solder barrel'));}
 const module=rearSlab(host.body,18,18,.8,.1,spec.module.position,dark,'Cat1-CN actual ML307R-DL fixed module substrate,envelope inferred'),shield=rearSlab(host.body,17.2,17.0,1.5,.18,[0,-3,.8],materials.metal(0xb8bdb1,{roughness:.64}),'Cat1-CN actual fixed ML307R shield,installed dimensions inferred'),lands=[];for(const sign of[-1,1])for(let i=0;i<18;i++){lands.push(mesh(host.body,new THREE.BoxGeometry(.8,.35,.07),metal,[sign*8.6,-3+(i-8.5)*.85,1.58],'Cat1-CN module perimeter solder-land appearance,not pin mapping'));lands.push(mesh(host.body,new THREE.BoxGeometry(.35,.8,.07),metal,[(i-8.5)*.85,-3+sign*8.6,1.58],'Cat1-CN module perimeter solder-land appearance,not pin mapping'));}
 const regulator=rearSlab(host.body,3,3,1,.12,[4.7,-15.1,1.6],dark,'Cat1-CN U1 actual SY8003ADFC converter package'),regulatorLeads=[];for(const sign of[-1,1])for(let i=0;i<5;i++)regulatorLeads.push(mesh(host.body,new THREE.BoxGeometry(.25,.55,.15),metal,[4.7+(i-2)*.5,-15.1+sign*1.55,1.52],'Cat1-CN U1 fixed physical solder terminal'));const inductor=rearSlab(host.body,3,3,1.2,.16,[.2,-15.2,1.6],dark,'Cat1-CN L1 actual WPN3012H2R2MT inductor envelope'),bulk=rearSlab(host.body,5.1,3.6,2.5,.18,[-5.7,-15.3,1.6],dark,'Cat1-CN C9 actual220uF fixed bulk capacitor package'),protection=rearSlab(host.body,2.1,1.3,.9,.08,[8.5,8.4,1.6],dark,'Cat1-CN U4 actual SMF05CT1G SIM protection package');const transistors=[];for(const[x,y]of[[-7.7,-27.6],[7.5,-27.4],[7.8,-29.2]]){const q=rearSlab(host.body,1.7,1.0,.8,.06,[x,y,1.6],dark,'Cat1-CN actual SS8050 fixed transistor package');transistors.push(q);for(const dx of[-.6,0,.6])mesh(host.body,new THREE.BoxGeometry(.3,.55,.12),metal,[x+dx,y-.65,1.54],'Cat1-CN actual transistor solder terminal');}const passives=[];const layout=[['C1',8.6,-15.4],['C2',7.9,-12.5],['C3',-8.8,-13.5],['C4',-8.8,-16.7],['C5',-1.5,-13.8],['C6',-8.7,3.8],['C7',6.8,20.5],['C8',8.5,18.2],['C10',8.5,15.7],['C11',-8.6,20.5],['R1',2.8,-17.8],['R2',4.0,-17.8],['R3',6.3,-28.8],['R4',-7.7,-25.8],['R5',-8.9,-28.7],['R6',8.8,7.9],['R7',8.8,5.8],['R8',8.8,3.7],['R9',8.8,1.6],['R10',6.7,18.3],['R11',-8.8,-1.5],['R12',6.7,16.2],['R13',6.7,14.1],['R14',-8.8,-3.7],['R15',-8.8,-5.9]];for(const[n,x,y]of layout){const q=rearSlab(host.body,1.0,.6,.45,.04,[x,y,1.6],n[0]==='C'?ceramic:dark,'Cat1-CN actual fixed '+n+' package,pose inferred');passives.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.16,.6,.12),metal,[x+sign*.43,y,1.54],'Cat1-CN actual fixed passive solder end');}const led=rearSlab(host.body,1.6,.8,.55,.05,[7,-25.8,1.6],materials.plastic(0xc9c2a2,{roughness:.9}),'Cat1-CN D1 actual fixed internal NETLIGHT0603 package,nonemissive/noexteriorAPI'),testPads=[];for(let i=0;i<8;i++)testPads.push(mesh(host.body,new THREE.CylinderGeometry(.35,.35,.06,24).rotateX(Math.PI/2),materials.metal(0xb39c57,{roughness:.5}),[-8.6+(i%2)*1.7,11.6+Math.floor(i/2)*2.2,1.57],'Cat1-CN actual fixed debug/USB/control test-pad envelope,not USB connector'));return{pcb,pads,barrels,module,shield,lands,regulator,regulatorLeads,inductor,bulk,protection,transistors,passives,led,testPads};}
function simAssembly(host,service){const frame=new THREE.Group();frame.name='Cat1-CN actual internal fixed Nano-SIM metal-cover holder';frame.position.fromArray(spec.sim.position);frame.quaternion.copy(FACE.back);host.body.add(frame);const black=materials.plastic(0x171e18,{roughness:.88}),metal=materials.metal(0xb9bfb2,{roughness:.5}),gold=materials.metal(0xbca35e,{roughness:.5}),base=slab(frame,14.2,12.6,.45,.4,[0,0,0],black,[],.01);base.name='Cat1-CN Nano-SIM actual fixed dielectric base';const rails=[];for(const sign of[-1,1])rails.push(mesh(frame,new THREE.BoxGeometry(.75,11.5,.8),black,[sign*6.6,0,.8],'Cat1-CN Nano-SIM real side guide/support'));const contacts=[];for(const x of[-2.0,2.0])for(const y of[-2.6,0,2.6])contacts.push(mesh(frame,new THREE.BoxGeometry(1.2,1.7,.18),gold,[x,y,.65],'Cat1-CN Nano-SIM fixed gold contact-leaf appearance'));
 const shape=roundedRect(12.6,11.2,.55);shape.holes.push(roundedRect(2.1,7.2,1.05,{path:new THREE.Path(),clockwise:true}));for(const y of[-3,0,3]){const h=new THREE.Path();h.absarc(-3.7,y,.6,0,tau,false);shape.holes.push(h);}const cover=solid(frame,shape,.22,[0,0,1.1],metal,'Cat1-CN actual fixed metal SIM cover with true central and three inspection apertures');const hinges=[];for(const x of[-4.1,0,4.1])hinges.push(mesh(frame,new THREE.CylinderGeometry(.48,.48,2.0,24).rotateZ(Math.PI/2),metal,[x,5.7,1.0],'Cat1-CN real fixed Nano-SIM cover hinge/retention barrel,noinventedmotion'));const tails=[];for(const sign of[-1,1])for(let i=0;i<4;i++)tails.push(mesh(frame,new THREE.BoxGeometry(1.4,.65,.13),metal,[sign*7.0,(i-1.5)*2.4,.065],'Cat1-CN Nano-SIM actual fixed socket solder tail envelope'));const anchor=service?host.add(new Component({id:'sim',label:'Internal Nano-SIM holder · rear cover removed',position:spec.sim.position,meta:{role:'visual-anchor',serviceOnly:true,source:'Own official SIM instructions require removal of three rear screws/cover;own bare-board photograph proves fixed metal flip-cover holder',scope:'Passive socket location only.No exterior click-through,card/tray accessory,guessed hinge motion,SIM data,authentication,cellular,network,electrical or firmware behavior'}})):null;return{frame,base,rails,contacts,cover,hinges,tails,anchor};}
function feedline(host){const frame=new THREE.Group();frame.name='Cat1-CN actual fixed IPEX and black coax feedline';frame.position.set(-8.0,8.5,1.6);frame.quaternion.copy(FACE.back);host.body.add(frame);const gold=materials.metal(0xc2ab60,{roughness:.45}),base=slab(frame,3.1,3.1,.25,.2,[0,0,0],materials.plastic(0xc9c5a3,{roughness:.8}),[],.005);base.name='Cat1-CN actual IPEX board receptacle dielectric';const socket=ring(frame,.95,.3,.5,[0,0,.25],gold,'Cat1-CN actual IPEX socket annulus'),plug=mesh(frame,new THREE.CylinderGeometry(1.0,1.0,.4,32).rotateX(Math.PI/2),gold,[0,0,.85],'Cat1-CN actual fixed IPEX cable plug cap');const points=[[-8,8.5,.55],[-9.1,12.5,.35],[-9.1,21,.25],[-6,24.0,.1],[-2,24.5,0],[0,24.3,0]],curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p))),coax=mesh(host.body,new THREE.TubeGeometry(curve,72,.45,10,false),materials.plastic(0x1c221c,{roughness:.87}),[0,0,0],'Cat1-CN actual fixed black IPEX-to-SMA coax pigtail,route inferred');return{frame,base,socket,plug,coax};}
function screws(host){const out=[],metal=materials.metal(0xaab4a6,{roughness:.46});for(const[x,y]of spec.rearCover.screwPositions){const s=new THREE.Shape();s.absarc(0,0,1.55,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=i*tau/6;if(i)h.lineTo(.62*Math.cos(a),.62*Math.sin(a));else h.moveTo(.62*Math.cos(a),.62*Math.sin(a));}h.closePath();s.holes.push(h);const head=solid(host.body,s,.45,[x,y,-3.95],metal,'Cat1-CN actual removable rear-cover retaining screw head'),blind=mesh(host.body,new THREE.CylinderGeometry(.62,.62,.12,6).rotateX(Math.PI/2),materials.metal(0x596253),[x,y,-3.44],'Cat1-CN actual rear screw blind hex floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.58,.58,4.8,24).rotateX(Math.PI/2),metal,[x,y,-.8],'Cat1-CN actual removable rear-cover screw shank');out.push({head,blind,shank});}return out;}
export function buildCat1CN(host,{rearCover=true,antenna=false,antennaAngleDeg=0}={}){if(typeof rearCover!=='boolean'||typeof antenna!=='boolean')throw new TypeError('rearCover/antenna must be booleans');const selected=data.filter(p=>rearCover||p.assemblySubset==='front'),parts=addCadParts(host,selected,{shell:materials.plastic(0x393d39,{roughness:.9})}),pcb=board(host),sim=simAssembly(host,!rearCover),radio=feedline(host),input=grove(host),rf=sma(host),fixing=rearCover?screws(host):[],labels={};for(const face of rearCover?['front','back']:['front']){const v=spec.labels[face],p=slab(host.body,...v.size,.08,.1,v.position,materials.plastic(0xdce0d9,{roughness:.9}),[],.005);p.name='Cat1-CN real '+face+' body adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}host.cat1CnAssembly={rearCover,parts,pcb,sim,radio,input,sma:rf,fixing,labels};host.unitStickers=addStickers(host);if(antenna)rf.port.attach(new Antenna({angleDeg:antennaAngleDeg}));}
